module reberland_linguistics (\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [7:0] char_in,\n    input wire [4:0] str_len,\n    output reg done,\n    output reg [4:0] suffix_count,\n    output reg [7:0] suffix_char,\n    output reg [2:0] suffix_len,\n    output reg [2:0] output_index\n);\n\n    // State declarations\n    localparam [2:0] IDLE    = 3'b000;\n    localparam [2:0] COMPUTE = 3'b001;\n    localparam [2:0] VALIDATE= 3'b010;\n    localparam [2:0] OUTPUT = 3'b011;\n    localparam [2:0] DONE_ST = 3'b100;\n\n    reg [2:0] state, next_state;\n    reg [4:0] pos;\n    reg [4:0] root_min;\n    reg [15:0] dp2;\n    reg [15:0] dp3;\n    reg [23:0] suffix_storage [0:7];\n    reg [2:0] stored_count;\n    reg [2:0] output_ptr;\n    reg [7:0] string_buf [0:15];\n    integer i, j;\n\n    // State machine\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            done <= 1'b0;\n            suffix_count <= 5'd0;\n            suffix_char <= 8'd0;\n            suffix_len <= 3'd0;\n            output_index <= 3'd0;\n            pos <= 5'd0;\n            stored_count <= 3'd0;\n            output_ptr <= 3'd0;\n            dp2 <= 16'd0;\n            dp3 <= 16'd0;\n            for (i = 0; i < 16; i = i + 1) string_buf[i] <= 8'd0;\n            for (j = 0; j < 8; j = j + 1) suffix_storage[j] <= 24'd0;\n        end else begin\n            state <= next_state;\n\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    if (start) begin\n                        // Initialize buffers\n                        for (i = 0; i < str_len; i = i + 1) begin\n                            string_buf[i] <= char_in;  // Simplified - actual input handling needed\n                        end\n                        root_min <= 5'd5;\n                        pos <= str_len - 1;\n                        dp2 <= 16'd0;\n                        dp3 <= 16'd0;\n                        if (str_len >= 5'd7) dp2[str_len-2] <= 1'b1;\n                        if (str_len >= 5'd8) dp3[str_len-3] <= 1'b1;\n                        next_state <= COMPUTE;\n                    end\n                end\n\n                COMPUTE: begin\n                    if (pos >= root_min) begin\n                        // Update DP tables\n                        if ((pos <= str_len-2) && \n                            ((dp2[pos+2] && (string_buf[pos] != string_buf[pos+2]) && (string_buf[pos+1] != string_buf[pos+3])) || dp3[pos+2])) begin\n                            dp2[pos] <= 1'b1;\n                        end\n                        if ((pos <= str_len-3) && \n                            ((dp3[pos+3] && (string_buf[pos] != string_buf[pos+3]) && \n                             (string_buf[pos+1] != string_buf[pos+4]) && \n                             (string_buf[pos+2] != string_buf[pos+5])) || dp2[pos+3])) begin\n                            dp3[pos] <= 1'b1;\n                        end\n                        next_state <= VALIDATE;\n                    end else begin\n                        next_state <= OUTPUT;\n                    end\n                end\n\n                VALIDATE: begin\n                    // Store valid suffixes\n                    if (dp2[pos] && (stored_count < 3'd7)) begin\n                        suffix_storage[stored_count] <= {8'h00, string_buf[pos], string_buf[pos+1]};\n                        stored_count <= stored_count + 3'd1;\n                    end\n                    if (dp3[pos] && (stored_count < 3'd7)) begin\n                        suffix_storage[stored_count] <= {string_buf[pos], string_buf[pos+1], string_buf[pos+2]};\n                        stored_count <= stored_count + 3'd1;\n                    end\n                    pos <= pos - 5'd1;\n                    next_state <= COMPUTE;\n                end\n\n                OUTPUT: begin\n                    // Bubble sort implementation\n                    if (output_ptr < stored_count - 3'd1) begin\n                        reg [23:0] temp;\n                        if (suffix_storage[output_ptr+1] < suffix_storage[output_ptr]) begin\n                            temp = suffix_storage[output_ptr];\n                            suffix_storage[output_ptr] <= suffix_storage[output_ptr+1];\n                            suffix_storage[output_ptr+1] <= temp;\n                        end\n                        output_ptr <= output_ptr + 3'd1;\n                    end else begin\n                        output_ptr <= 3'd0;\n                        next_state <= DONE_ST;\n                        suffix_count <= stored_count;\n                    end\n                end\n\n                DONE_ST: begin\n                    if (output_ptr < stored_count) begin\n                        suffix_char <= suffix_storage[output_ptr][15:8];\n                        suffix_len <= (suffix_storage[output_ptr][23:16] == 8'h00) ? 3'd2 : 3'd3;\n                        output_index <= output_ptr + 3'd1;\n                        output_ptr <= output_ptr + 3'd1;\n                    end else begin\n                        done <= 1'b1;\n                        next_state <= IDLE;\n                    end\n                end\n\n                default: next_state <= IDLE;\n            endcase\n        end\n    end\n\nendmodule